import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_conv2d(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
    int64_t stride_h, int64_t stride_w,
    int64_t pad_h, int64_t pad_w,
    int64_t dil_h, int64_t dil_w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
#define BLOCK_H 16
#define BLOCK_W 16
#define RTH 2
#define RTW 4
#define OC_TILE 8
#define TILE_H (BLOCK_H * RTH)
#define TILE_W (BLOCK_W * RTW)
__global__ void cute_conv2d_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ w_ptr,
    const float* __restrict__ bias_ptr,
    float* __restrict__ y_ptr,
    int N, int Cin, int H, int W,
    int Cout, int KH, int KW,
    int OH, int OW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int tile_in_h, int tile_in_w,
    int Cout_tiles,
    bool has_bias)
{
    extern __shared__ float smem[];
    int n  = blockIdx.z / Cout_tiles;
    int oc_tile = blockIdx.z % Cout_tiles;
    int oc0 = oc_tile * OC_TILE;
    int oh0 = blockIdx.y * TILE_H;
    int ow0 = blockIdx.x * TILE_W;
    int th = threadIdx.y;
    int tw = threadIdx.x;
    int oh_idx[RTH];
    int ow_idx[RTW];
    bool oh_valid[RTH];
    bool ow_valid[RTW];
    #pragma unroll
    for (int ph = 0; ph < RTH; ++ph) {
        oh_idx[ph] = oh0 + ph * BLOCK_H + th;
        oh_valid[ph] = oh_idx[ph] < OH;
    }
    #pragma unroll
    for (int pw = 0; pw < RTW; ++pw) {
        ow_idx[pw] = ow0 + tw * RTW + pw;
        ow_valid[pw] = ow_idx[pw] < OW;
    }
    float acc[OC_TILE][RTH][RTW];
    #pragma unroll
    for (int t = 0; t < OC_TILE; ++t) {
        #pragma unroll
        for (int ph = 0; ph < RTH; ++ph) {
            #pragma unroll
            for (int pw = 0; pw < RTW; ++pw) {
                acc[t][ph][pw] = 0.f;
            }
        }
    }
    // Weight tensor view: (Cout, Cin, KH, KW)
    Tensor gW = make_tensor(make_gmem_ptr(w_ptr),
                             make_shape(Cout, Cin, KH, KW),
                             make_stride(Cin * KH * KW, KH * KW, KW, 1));
    int n_threads = BLOCK_H * BLOCK_W;
    int flat_tid = th * BLOCK_W + tw;
    int tile_elems = tile_in_h * tile_in_w;
    int smem_pad = 4; // padding (in floats) to reduce shared-memory bank conflicts across rows
    int padded_w = tile_in_w + smem_pad;
    int tile_elems_padded = tile_in_h * padded_w;
    // Stage this block's weight slice for OC_TILE output channels into
    // shared memory once. The input tile below is shared (reused) across
    // all OC_TILE output channels computed by this block, cutting
    // redundant global memory traffic for the input by a factor of
    // OC_TILE compared to one-output-channel-per-block.
    int weight_elems_per_oc = Cin * KH * KW;
    int weight_elems = weight_elems_per_oc * OC_TILE;
    float* sw_ptr = smem + 2 * tile_elems_padded;
    Tensor sW = make_tensor(make_smem_ptr(sw_ptr),
                             make_shape(OC_TILE, Cin, KH, KW),
                             make_stride(Cin * KH * KW, KH * KW, KW, 1));
    bool full_oc_tile = (oc0 + OC_TILE) <= Cout;
    bool vec_ok = full_oc_tile && (weight_elems % 4 == 0) && (tile_elems % 2 == 0);
    if (vec_ok) {
        const float4* w_vec_ptr = reinterpret_cast<const float4*>(w_ptr + (int64_t)oc0 * (int64_t)weight_elems_per_oc);
        float4* sw_vec_ptr = reinterpret_cast<float4*>(sw_ptr);
        int vec_elems = weight_elems / 4;
        for (int idx = flat_tid; idx < vec_elems; idx += n_threads) {
            sw_vec_ptr[idx] = w_vec_ptr[idx];
        }
    } else {
        for (int idx = flat_tid; idx < weight_elems; idx += n_threads) {
            int t_w = idx / weight_elems_per_oc;
            int rem0 = idx % weight_elems_per_oc;
            int ic_w = rem0 / (KH * KW);
            int rem_w = rem0 % (KH * KW);
            int kh_w = rem_w / KW;
            int kw_w = rem_w % KW;
            int oc_w = oc0 + t_w;
            sw_ptr[idx] = (oc_w < Cout) ? gW(oc_w, ic_w, kh_w, kw_w) : 0.f;
        }
    }
    // Double-buffered shared memory tiles to pipeline the load of the next
    // input channel's tile with the compute on the current channel's tile.
    float* smem_buf[2] = { smem, smem + tile_elems_padded };
    Tensor sX0 = make_tensor(make_smem_ptr(smem_buf[0]),
                              make_shape(tile_in_h, tile_in_w),
                              make_stride(padded_w, 1));
    Tensor sX1 = make_tensor(make_smem_ptr(smem_buf[1]),
                              make_shape(tile_in_h, tile_in_w),
                              make_stride(padded_w, 1));
    auto load_tile = [&](int ic, float* dst_buf) {
        const float* x_slice = x_ptr + ((int64_t)n * Cin + ic) * (int64_t)H * (int64_t)W;
        Tensor gX = make_tensor(make_gmem_ptr(x_slice),
                                 make_shape(H, W),
                                 make_stride(W, 1));
        int in_col0_base = ow0 * stride_w - pad_w;
        bool w_div4 = (W % 4 == 0);
        bool col_base_aligned = (((in_col0_base % 4) + 4) % 4) == 0;
        bool tile_w_div4 = (tile_in_w % 4 == 0);
        bool use_vec = w_div4 && col_base_aligned && tile_w_div4;
        if (use_vec) {
            int w4 = tile_in_w / 4;
            int vec_elems = tile_in_h * w4;
            for (int idx = flat_tid; idx < vec_elems; idx += n_threads) {
                int r = idx / w4;
                int cb = idx % w4;
                int c0 = cb * 4;
                int in_row = oh0 * stride_h - pad_h + r;
                int in_col0 = in_col0_base + c0;
                float4 v4;
                if (in_row >= 0 && in_row < H && in_col0 >= 0 && (in_col0 + 3) < W) {
                    const float4* src = reinterpret_cast<const float4*>(x_slice + (int64_t)in_row * W + in_col0);
                    v4 = *src;
                } else if (in_row >= 0 && in_row < H) {
                    float tmp0 = (in_col0 >= 0 && in_col0 < W) ? gX(in_row, in_col0) : 0.f;
                    float tmp1 = (in_col0 + 1 >= 0 && in_col0 + 1 < W) ? gX(in_row, in_col0 + 1) : 0.f;
                    float tmp2 = (in_col0 + 2 >= 0 && in_col0 + 2 < W) ? gX(in_row, in_col0 + 2) : 0.f;
                    float tmp3 = (in_col0 + 3 >= 0 && in_col0 + 3 < W) ? gX(in_row, in_col0 + 3) : 0.f;
                    v4 = make_float4(tmp0, tmp1, tmp2, tmp3);
                } else {
                    v4 = make_float4(0.f, 0.f, 0.f, 0.f);
                }
                float4* dst4 = reinterpret_cast<float4*>(dst_buf + (int64_t)r * padded_w + c0);
                *dst4 = v4;
            }
        } else {
            Tensor sX_dst = make_tensor(make_smem_ptr(dst_buf),
                                         make_shape(tile_in_h, tile_in_w),
                                         make_stride(padded_w, 1));
            for (int idx = flat_tid; idx < tile_elems; idx += n_threads) {
                int r = idx / tile_in_w;
                int c = idx % tile_in_w;
                int in_row = oh0 * stride_h - pad_h + r;
                int in_col = ow0 * stride_w - pad_w + c;
                float v = 0.f;
                if (in_row >= 0 && in_row < H && in_col >= 0 && in_col < W) {
                    v = gX(in_row, in_col);
                }
                sX_dst(r, c) = v;
            }
        }
    };
    if (Cin > 0) {
        load_tile(0, smem_buf[0]);
    }
    __syncthreads();
    for (int ic = 0; ic < Cin; ++ic) {
        int cur = ic & 1;
        int nxt = cur ^ 1;
        if (ic + 1 < Cin) {
            load_tile(ic + 1, smem_buf[nxt]);
        }
        auto& sX = (cur == 0) ? sX0 : sX1;
        #pragma unroll
        for (int kh = 0; kh < KH; ++kh) {
            #pragma unroll
            for (int kw = 0; kw < KW; ++kw) {
                float xv[RTH][RTW];
                #pragma unroll
                for (int ph = 0; ph < RTH; ++ph) {
                    int sh_row = (th + ph * BLOCK_H) * stride_h + kh * dil_h;
                    #pragma unroll
                    for (int pw = 0; pw < RTW; ++pw) {
                        int sh_col = (tw * RTW + pw) * stride_w + kw * dil_w;
                        xv[ph][pw] = sX(sh_row, sh_col);
                    }
                }
                #pragma unroll
                for (int t = 0; t < OC_TILE; ++t) {
                    float wt = sW(t, ic, kh, kw);
                    #pragma unroll
                    for (int ph = 0; ph < RTH; ++ph) {
                        #pragma unroll
                        for (int pw = 0; pw < RTW; ++pw) {
                            acc[t][ph][pw] += xv[ph][pw] * wt;
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    Tensor gY = make_tensor(make_gmem_ptr(y_ptr),
                             make_shape(N, Cout, OH, OW),
                             make_stride(Cout * OH * OW, OH * OW, OW, 1));
    #pragma unroll
    for (int t = 0; t < OC_TILE; ++t) {
        int oc = oc0 + t;
        if (oc >= Cout) continue;
        float bval = has_bias ? bias_ptr[oc] : 0.f;
        #pragma unroll
        for (int ph = 0; ph < RTH; ++ph) {
            if (!oh_valid[ph]) continue;
            if (ow_valid[RTW - 1]) {
                float4 v4;
                v4.x = acc[t][ph][0] + bval;
                v4.y = acc[t][ph][1] + bval;
                v4.z = acc[t][ph][2] + bval;
                v4.w = acc[t][ph][3] + bval;
                float* dst = y_ptr + (((int64_t)n * Cout + oc) * OH + oh_idx[ph]) * OW + ow_idx[0];
                *reinterpret_cast<float4*>(dst) = v4;
            } else {
                #pragma unroll
                for (int pw = 0; pw < RTW; ++pw) {
                    if (!ow_valid[pw]) continue;
                    gY(n, oc, oh_idx[ph], ow_idx[pw]) = acc[t][ph][pw] + bval;
                }
            }
        }
    }
}
torch::Tensor cute_conv2d(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
    int64_t stride_h, int64_t stride_w,
    int64_t pad_h, int64_t pad_w,
    int64_t dil_h, int64_t dil_w)
{
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
                "expect float32 tensors");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D (Cout,Cin,KH,KW)");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    bool has_bias = bias.defined() && bias.numel() > 0;
    torch::Tensor bias_c;
    if (has_bias) {
        TORCH_CHECK(bias.is_cuda() && bias.scalar_type() == at::kFloat, "bias must be float32 CUDA");
        bias_c = bias.contiguous();
    }
    int N    = (int)x_c.size(0);
    int Cin  = (int)x_c.size(1);
    int H    = (int)x_c.size(2);
    int W    = (int)x_c.size(3);
    int Cout = (int)w_c.size(0);
    int KH   = (int)w_c.size(2);
    int KW   = (int)w_c.size(3);
    TORCH_CHECK((int)w_c.size(1) == Cin, "weight Cin mismatch");
    int OH = (H + 2 * (int)pad_h - (int)dil_h * (KH - 1) - 1) / (int)stride_h + 1;
    int OW = (W + 2 * (int)pad_w - (int)dil_w * (KW - 1) - 1) / (int)stride_w + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "invalid output size");
    auto y = torch::empty({N, Cout, OH, OW}, x_c.options());
    int tile_in_h = (TILE_H - 1) * (int)stride_h + (int)dil_h * (KH - 1) + 1;
    int tile_in_w = (TILE_W - 1) * (int)stride_w + (int)dil_w * (KW - 1) + 1;
    int Cout_tiles = (Cout + OC_TILE - 1) / OC_TILE;
    size_t smem_bytes = (size_t)tile_in_h * (size_t)(tile_in_w + 4) * sizeof(float) * 2
                       + (size_t)Cin * (size_t)KH * (size_t)KW * sizeof(float) * (size_t)OC_TILE;
    if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(cute_conv2d_kernel,
                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                              (int)smem_bytes);
    }
    dim3 block(BLOCK_W, BLOCK_H, 1);
    dim3 grid((OW + TILE_W - 1) / TILE_W,
              (OH + TILE_H - 1) / TILE_H,
              (unsigned int)(N * Cout_tiles));
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_conv2d_kernel<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        has_bias ? bias_c.data_ptr<float>() : nullptr,
        y.data_ptr<float>(),
        N, Cin, H, W,
        Cout, KH, KW,
        OH, OW,
        (int)stride_h, (int)stride_w,
        (int)pad_h, (int)pad_w,
        (int)dil_h, (int)dil_w,
        tile_in_h, tile_in_w,
        Cout_tiles,
        has_bias
    );
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE conv2d launch failed");
    return y;
}
"""

cute_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv2d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False) -> None:
        super().__init__()
        # Keep an nn.Conv2d purely as a parameter container (weight/bias init),
        # but perform the actual computation with our custom CUTE kernel.
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size,
                                 stride=stride, padding=padding, dilation=dilation, bias=bias)
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv2d.weight
        bias = self.conv2d.bias
        stride = self.conv2d.stride
        padding = self.conv2d.padding
        dilation = self.conv2d.dilation

        if bias is None:
            bias_t = torch.empty(0, device=x.device, dtype=x.dtype)
        else:
            bias_t = bias

        x = x.contiguous().float()
        weight = weight.contiguous().float()

        out = self._ext.cute_conv2d(
            x, weight, bias_t,
            int(stride[0]), int(stride[1]),
            int(padding[0]), int(padding[1]),
            int(dilation[0]), int(dilation[1]),
        )
        return out

