    cute_conv2d_kernel<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        has_bias ? bias_c.data_ptr<float>() : nullptr,
        y.data_ptr<float>(),
        N, Cin, H, W,
        Cout, KH, KW,
        OH, OW,
        (int)stride_h, (int)stride_w,
        (int)pad_h, (int)pad_w,
        (int)dil_h, (int)dil_w,
